T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def variants(S):
  outs=[]
  for k in range(4):
    for ref in [False,True]:
      pts=[]
      for r,c in S:
        if ref:c=-c
        for _ in range(k):r,c=c,-r
        pts.append((r,c))
      mr=min(r for r,c in pts); mc=min(c for r,c in pts)
      norm=frozenset((r-mr,c-mc) for r,c in pts)
      if norm not in [x[0] for x in outs]:outs.append((norm,(k,ref)))
  return outs
Vs=variants(T)
def fits(seed):
  results=[]
  for shape,o in Vs:
    h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
    # map seed to relative anchors by each matching template point and each seed point
    for sr,sc in seed:
      for tr,tc in shape:
        r0,c0=sr-tr,sc-tc
        if all((r-r0,c-c0) in shape for r,c in seed):
          results.append((o,shape,(r0,c0),len(shape)-len(seed)))
  return results
